import {preProviderRecoveryCandidate} from './simulation-pre-provider-recovery.mjs';
import {renderLabGraphDiff as graphDiff} from './lab-graph-diff.mjs';
import {simulationMarketScope,simulationObservedCosts,simulationEventReturnBasis} from './simulation-asset-scope.mjs';
import {partialPortfolioValuation,partialEventValuation,simulationValuationStatus,completeReferenceValuation,activeReferenceValuation,comparableReferenceValuations,referenceValuationStatus,referenceValuationSources} from './simulation-valuation.mjs';
import {helpTooltip} from './help-tooltip.mjs';
import {renderActionMenu} from './action-menu.mjs';
import {renderBenchmarkPicker} from './benchmark-picker.mjs';
import {renderSimulationBaselineComparison} from './simulation-baseline-comparison.mjs';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=v=>Number.isFinite(v)?(v*100).toFixed(2)+'%':'—';
const num=v=>Number.isFinite(v)?new Intl.NumberFormat('ko-KR',{maximumFractionDigits:2}).format(v):'—';
const date=v=>v&&Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v)):'기간 선택';
const button=(label,action,id='',disabled=false,primary=false)=>`<button class="button small${primary?' primary':''}" type="button" data-lab-action="${action}" data-lab-id="${esc(id)}" ${disabled?'disabled':''}>${esc(label)}</button>`;
const status=s=>({CREATED:'실행 준비',RUNNING:'실행 중',PAUSED:'일시중지',COMPLETED:'완료',ACTION_REQUIRED:'응답 확인',FAILED:'실패'})[s]||'설정 중';
export function labWorkspaceStep(value){return ['strategy','period','review'].includes(value)?value:'strategy';}
export function labWorkspaceView(value,{complete=false,running=false}={}){return ['results','execution','conditions'].includes(value)?value:running||!complete?'execution':'results';}

export function eventDatasetPicker(d,caps,models=[],{refreshing=false}={}){
 const market=simulationMarketScope(d,caps),available=caps?.availableDatasets??caps?.datasets??[];
 if(!market.multiEvent)return `<div class="studio-sheet-body"><label class="field">기록한 호가·체결<select name="datasetId"><option value="">기록 선택</option>${available.map(dataset=>`<option value="${esc(dataset.id??dataset.datasetId)}" ${(dataset.id??dataset.datasetId)===d.datasetId?'selected':''}>${esc(dataset.label??dataset.name??dataset.id??dataset.datasetId)}${dataset.startAt?' · '+esc(date(dataset.startAt)):''}</option>`).join('')}</select></label></div>`;
 const selected=new Set(d.datasetIds??[]),graph=models[0]?.data?.strategyPlan?.graph,period=graph?.executionScope?.timeframe??market.timeframe,universe=models[0]?.data?.universe?.instrumentIds??[],rows=available.filter(item=>(!period||item.timeframe===period)&&(!universe.length||universe.includes(item.instrumentId))||selected.has(item.id??item.datasetId)),chosen=available.filter(item=>selected.has(item.id??item.datasetId)),currency=chosen[0]?.quoteCurrency??chosen[0]?.market?.split('-')[0],max=graph?.executionScope?.maxCandidates??caps?.limits?.maxCandidates??20;
 const reasons=refreshing?[]:(caps?.blockedReasons??[]).filter(reason=>!(reason.code==='EVENT_MULTI_DATASETS'&&selected.size<2));
 return `<div class="studio-sheet-body"><fieldset class="strategy-source-picks"><legend>후보별 호가·체결 기록 · ${selected.size}개 선택</legend>${rows.map(item=>{const id=item.id??item.datasetId,checked=selected.has(id),foreign=currency&&(item.quoteCurrency??item.market?.split('-')[0])!==currency,duplicate=chosen.some(other=>other.instrumentId===item.instrumentId&&(other.id??other.datasetId)!==id),disabled=!checked&&(selected.size>=max||foreign||duplicate);return `<label title="${esc(foreign?'같은 결제 통화의 자료를 선택하세요.':duplicate?'종목마다 하나의 기록을 선택하세요.':item.startAt+' — '+item.endAt)}"><input type="checkbox" name="datasetIds" value="${esc(id)}" ${checked?'checked':''} ${disabled?'disabled':''}/><span>${esc(item.label??item.name??item.market??id)} · ${esc(item.timeframe)}${item.startAt?' · '+esc(date(item.startAt)):''}</span></label>`;}).join('')||'<p class="empty">이 투자 범위와 주기에 맞는 저장 기록이 없습니다.</p>'}</fieldset><p class="tiny muted">같은 통화·분봉의 서로 다른 종목 2–${max}개를 선택하세요. ${helpTooltip('관측 기록 선택','마인드 투자 범위에서 종목마다 하나의 저장 기록을 고릅니다. 선택한 기록이 모두 존재하는 공통 기간과 당시 수수료로 두 전략을 비교합니다.',{id:'lab-datasets-help'})}</p>${refreshing?'<p role="status" class="tiny muted">선택한 '+selected.size+'개 기록의 공통 기간을 확인하는 중…</p>':reasons.length?`<p role="status" class="tiny muted">${reasons.map(reason=>esc(reason.message)).join(' · ')}</p>`:''}</div>`;
}

function planNavigation(step,loading=false){return `<nav class="lab-stepper" aria-label="비교 실험 준비">${[['strategy','전략 구성'],['period','기간 선택'],['review','실행 검토']].map(([id,label],i)=>`<button type="button" data-lab-action="step" data-lab-id="${id}" aria-current="${step===id?'step':'false'}" ${loading?'disabled':''}><span>${i+1}</span>${label}</button>`).join('')}</nav>`;}
function scopeLine(d,caps){const c=d.config??d;return `<div class="lab-context-line"><span>${esc(simulationMarketScope(d,caps).label)}</span><span>${esc(date(c.startAt))} — ${esc(date(c.endAt))} KST</span></div>`;}
function field(label,name,value,max){return `<label class="field">${label}<input name="${name}" type="number" min="0" step="${name==='maxJevCalls'?'1':'any'}" ${Number.isFinite(max)?`max="${max}"`:""} value="${esc(value)}"></label>`;}
function mindPicker(minds,d,index){const selected=index?d.bMindId||d.mindId:d.mindId;return `<label class="field"><span class="lab-arm-label">${index?'B · 비교 전략':'A · 기준 전략'}</span><select name="${index?'bMindId':'mindId'}"><option value="">마인드 선택</option>${minds.map(m=>`<option value="${esc(m.id)}" ${m.id===selected?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`;}

function progress(a,b){const done=(a.progress?.processed??0)+(b?.progress?.processed??0),total=(a.progress?.total??0)+(b?.progress?.total??0);return `<div class="lab-progress-strip" role="status"><span>${preProviderRecoveryCandidate(a)?'호출 전 계산 오류':status(a.status)}${b?' / '+(preProviderRecoveryCandidate(b)?'호출 전 계산 오류':status(b.status)):''}</span><progress aria-label="비교 실험 진행" value="${done}" max="${total||1}"></progress><span>${done} / ${total}봉</span></div>`;}
export function labReportDestination(a,b,id,profileId='all'){return {profileId,view:'simulations',lab:null,labStep:null,labView:null,draftId:null,a:null,b:null,comparisonA:a.id,comparisonB:b?.id??null,simulationId:id,learningId:null,learningView:null,learningStep:null,previousLearningId:null,setup:null,setupStep:null,prepare:null,tab:'overview',cursor:null};}
function resultRows(a,b,href,profileId){const qqq=a?.benchmarks?.qqqBuyAndHold??a?.report?.benchmarks?.qqqBuyAndHold,session=simulationMarketScope(a).sessionRule,eventStream=simulationMarketScope(a).eventStream,eventBasis=simulationEventReturnBasis(a),referenceMode=Boolean((partialPortfolioValuation(a)||partialPortfolioValuation(b))&&completeReferenceValuation(a)&&completeReferenceValuation(b)),portfolio=simulationMarketScope(a).portfolio||simulationMarketScope(a).btcValuation,baseline=a?.benchmarks?.btcHold??a?.report?.benchmarks?.btcHold??b?.benchmarks?.btcHold??b?.report?.benchmarks?.btcHold;return `<div class="table-scroll"><table class="lab-result-table"><thead><tr><th>전략</th><th>${referenceMode?'참고 NAV 수익률':eventStream?eventBasis.label+helpTooltip(eventBasis.label,eventBasis.help,{id:'lab-event-return-basis'}):[a,b].filter(Boolean).some(s=>s.status==='COMPLETED'&&s.evaluationEligibility?.wholeWindowComparable===false)?'계좌 수익률':'순수익률'}</th><th>${eventStream?eventBasis.drawdownLabel:'최대 낙폭'}</th><th>체결</th><th></th></tr></thead><tbody>${[a,b].filter(Boolean).map((s,i)=>{const nav=referenceMode?completeReferenceValuation(s):activeReferenceValuation(s),metrics=nav?.metrics??s.metrics,nativeLabel=eventStream?simulationEventReturnBasis(s).nativeLabel:null,name=s.manifest?.data.name||s.name||'저장된 전략',label=(i?'B · 비교':'A · 기준')+' · '+name+' 결과 보기',destination=href?.('minds',labReportDestination(a,b,s.id,profileId)),nameControl=destination?`<a class="lab-result-name" href="${esc(destination)}" data-lab-action="report" data-lab-id="${esc(s.id)}" aria-label="${esc(label)}" title="${esc(name)}"><span>${esc(name)}</span></a>`:`<button class="lab-result-name" type="button" data-lab-action="report" data-lab-id="${esc(s.id)}" aria-label="${esc(label)}" title="${esc(name)}"><span>${esc(name)}</span></button>`;return `<tr><th scope="row"><span class="lab-arm-label">${i?'B · 비교':'A · 기준'}</span>${nameControl}${nav?referenceValuationStatus(s,{id:'lab-result-reference-'+i,force:referenceMode}):simulationValuationStatus(s,{id:'lab-result-valuation-'+i,showAmount:true})}</th><td>${(partialPortfolioValuation(s)||partialEventValuation(s))&&!nav?'—':pct(metrics?.totalReturn)}${nativeLabel?`<div class="muted"><small>${esc(nativeLabel)}</small></div>`:''}</td><td>${(partialPortfolioValuation(s)||partialEventValuation(s))&&!nav?'—':pct(metrics?.maxDrawdown)}</td><td>${num(s.rowsCounts?.fills??s.metrics?.tradeCount)}</td><td>${button('노드 편집','adopt',s.id,s.status!=='COMPLETED')}</td></tr>`;}).join('')}${session&&qqq?`<tr data-lab-qqq-baseline><th>QQQ 전액 보유${helpTooltip('QQQ 전액 보유','같은 기간과 초기 USD 자금으로 첫 시가 매수. 수수료, 가격 차이, 주식분할, 배당과 종료 청산 비용 반영.',{id:'lab-qqq-baseline-help'})}</th><td>${pct(qqq.totalReturn)}</td><td>${pct(qqq.maxDrawdown)}</td><td></td><td></td></tr>`:''}${portfolio?`<tr data-lab-btc-baseline><th>BTC 보유${helpTooltip('BTC 보유','같은 초기 BTC를 그대로 보유한 기준입니다. 수익률과 낙폭을 BTC 단위로 계산합니다.',{id:'lab-btc-baseline-help'})}</th><td>${pct(baseline?.totalReturn)}</td><td>${pct(baseline?.maxDrawdown)}</td><td>${num(baseline?.tradeCount)}</td><td></td></tr>`:''}</tbody></table></div>`;}
export function renderLabWorkspace({route,draft:d,a,b,models,minds,caps,loading,datasetRefreshing=false,busy,running,focusedArm,benchmarkFull,error,panel,consentControl,requiresConsent,comparable,comparisonReadiness,runnable,draftSaveState='',frameSequence=0,href}){
 const referenceComparable=comparableReferenceValuations(a,b);comparable=referenceComparable||Boolean(comparable)&&![a,b].some(partialPortfolioValuation);
 const market=simulationMarketScope(a??d??{},caps??{}),costs=simulationObservedCosts(a??{},caps,models),saved=!!a,step=labWorkspaceStep(route.params.get('labStep')),view=labWorkspaceView(route.params.get('labView'),{complete:a?.status==='COMPLETED'&&b?.status==='COMPLETED',running});
 const back=button('실험 목록','back'),primary=saved&&d&&!loading?(running?button('일시중지','pause','',false,true):!b?button('B 저장 재시도','save','',busy,true):runnable?button(a?.status==='CREATED'&&b?.status==='CREATED'?'비교 실행':'이어서 실행','run','',false,true):view==='conditions'?'':button('복제해서 편집','clone','',busy,true)):'';
 const title=saved||route.params.get('a')?'전략 비교':route.params.get('draftId')?'비교 실험 초안':'새 비교 실험';
 const finished=!loading&&a?.status==='COMPLETED'&&b?.status==='COMPLETED'&&[a,b].every(s=>Number.isSafeInteger(s.progress?.total)&&s.progress.total>0&&s.progress.processed===s.progress.total);
 const head=`<div class="lab-workspace-heading"><div>${back}<h2>${title}</h2>${finished?'<span class="pill" role="status" aria-label="A와 B 모두 완료">완료</span>':''}</div><div class="actions">${!saved&&d?`<span class="muted" role="status" aria-live="polite" aria-atomic="true" data-lab-draft-status>${esc(draftSaveState)}</span>${button('초안 저장','save-draft','',busy||loading||models.some(m=>!m))}`:''}${primary}${saved&&d&&!loading&&runnable&&view!=='conditions'?renderActionMenu({id:'lab-workspace-actions',label:'실험 작업',compact:true,content:button('복제해서 편집','clone','',busy||running)}):''}</div></div>`;
 if(!loading&&!d&&error)return `<section class="lab-workspace">${head}<p class="lab-inline-error" role="alert">${esc(error)}</p>${button('다시 불러오기','reload')}</section>`;
 if(loading&&!datasetRefreshing||!d)return `<section class="lab-workspace">${head}<p class="empty" role="status">실험을 불러오는 중…</p></section>`;
 let body='';
 if(!saved){
  const strategies=`<div class="lab-choose-minds">${mindPicker(minds,d,0)}${mindPicker(minds,d,1)}</div>${market.eventStream?'':`<details class="lab-template-picker"><summary>구성 예시에서 시작</summary><label class="field">비교 예시<select name="preset"><option value="CURRENT">현재 마인드</option>${market.portfolio?'':'<option value="TREND_VIBE" '+(d.template==='TREND_VIBE'?'selected':'')+'>추세 퀀트 · 상승장 바이브 비교</option>'}<option value="QUANT">${market.portfolio?'다종목 퀀트':'퀀트'}</option><option value="MIXED">${market.portfolio?'퀀트 + JEV 비중 조절':'퀀트 + 바이브'}</option>${market.portfolio?'':'<option value="VIBE">바이브</option>'}</select></label></details>`}<div class="simulation-lab-grid">${panel(models[0],null,0)}${panel(models[1],null,1)}</div>`;
  const period=`<section class="studio-sheet lab-period-stage"><div class="studio-sheet-head"><h3 tabindex="-1" data-lab-period-title>어느 시장에서 비교할까요?</h3>${helpTooltip('공통 테스트 기간','두 전략은 같은 기간·시세·초기 자금·거래 비용으로 실행합니다.',{id:'lab-period-common-help'})}</div>${market.eventStream?eventDatasetPicker(d,caps,models,{refreshing:datasetRefreshing}):''}${!datasetRefreshing&&caps?.benchmarkCatalog?renderBenchmarkPicker(caps.benchmarkCatalog,{startAt:d.startAt,endAt:d.endAt},{presetId:d.benchmarkPresetId,focused:true,full:benchmarkFull}):market.multiEvent?'':'<p class="empty">전략을 선택하면 테스트 기간이 표시됩니다.</p>'}</section>`;
  const review=`<div class="lab-review-layout"><section class="studio-sheet"><div class="studio-sheet-head"><h3>실행 조건</h3>${button('기간 변경','step','period')}</div><div class="studio-sheet-body">${scopeLine(d,caps)}<div class="lab-pair-names">${models.map((m,i)=>`<div><span>${i?'B · 비교':'A · 기준'}</span><strong>${esc(m?.data.name||'마인드 선택')}</strong></div>`).join('')}</div><details data-lab-conditions><summary>자금·거래 비용 <span data-lab-cost-summary>${market.amount(d.initialCash)} ${esc(market.currency)} · ${market.eventStream?esc(costs.feeLabel):num(d.feeBps)+'bp'}</span></summary><div class="simulation-lab-controls">${field('초기 자금 · '+market.currency,'initialCash',d.initialCash)}${market.eventStream?`<div class="field"><span>관측 수수료 ${helpTooltip('관측 수수료','선택한 기록의 계좌 수수료입니다. 매수·매도는 각각의 관측 비율을 사용합니다.'+(costs.feeDetails?' '+costs.feeDetails+'.':'')+(costs.fee?.observedAt?' 관측 '+date(costs.fee.observedAt)+' KST.':''),{id:'lab-event-fee-help'})}</span><output>${esc(costs.feeLabel)}</output></div><div class="field"><span>허용 가격 차이 ${helpTooltip('허용 가격 차이','각 전략의 주문 노드에서 수정합니다. 이 실험은 저장한 주문 설정을 사용합니다.',{id:'lab-event-slip-help'})}</span><output>${esc(costs.slippageLabel)}</output></div>`:field('수수료 · bp','feeBps',d.feeBps)+field('슬리피지 · bp','slippageBps',d.slippageBps)}${requiresConsent?field('각 실험의 최대 JEV 호출','maxJevCalls',d.maxJevCalls,caps?.limits?.maxJevCalls):''}</div></details><div data-lab-consent-container ${requiresConsent?'':'hidden'}>${requiresConsent?consentControl():''}</div></div></section>${graphDiff(models)}</div>`;
  const next=step==='strategy'?['period','기간 선택']:['review','실행 검토'];
  body=planNavigation(step,loading)+`<form data-lab-form ${busy?'inert aria-busy="true"':''}>${step==='strategy'?strategies:step==='period'?period:review}</form><footer class="lab-step-footer"><span>${step==='strategy'?'A와 B의 부품을 각각 편집하세요.':step==='period'?esc(date(d.startAt)+' — '+date(d.endAt)+' KST'):'조건을 저장한 뒤 실행할 수 있습니다.'}</span><div class="actions">${step!=='strategy'?button('이전','step',step==='review'?'period':'strategy',loading):''}${step==='review'?button(busy?'저장 중…':'비교 저장','save','',busy||loading||models.some(m=>!m),true):button(next[1],'step',next[0],busy||loading||models.some(m=>!m),true)}</div></footer>`;
 }else if(!b){
  body=scopeLine(d,caps)+`<section class="studio-sheet lab-saved-conditions"><div class="studio-sheet-head"><h3>B 저장 확인</h3>${button('복제해서 편집','clone','',busy)}</div><div class="studio-sheet-body"><p>A의 저장된 조건으로 B를 이어서 저장합니다.</p><dl><div><dt>A · 기준</dt><dd>${esc(a.manifest?.data.name||a.name)}</dd></div><div><dt>B · 비교</dt><dd>${esc(models[1]?.data.name||'선택한 전략')}</dd></div><div><dt>초기 자금</dt><dd>${market.amount(d.initialCash)} ${esc(market.currency)}</dd></div></dl>${requiresConsent?consentControl():''}${graphDiff(models)}</div></section>`;
 }else{
  const tabs=`<nav class="lab-view-tabs" aria-label="비교 실험 상세">${[['results','결과'],['execution','실행 그래프'],['conditions','실험 조건']].map(([id,label])=>`<button type="button" data-lab-action="view" data-lab-id="${id}" aria-current="${view===id?'page':'false'}">${label}</button>`).join('')}</nav>`;
  if(view==='execution')body=`<div class="lab-execution-toolbar">${!running&&a&&b&&a.progress.processed&&b.progress.processed?`<label class="field">판단 시점<select data-lab-frame>${Array.from({length:Math.min(a.progress.processed,b.progress.processed)},(_,i)=>`<option value="${i+1}" ${i+1===(frameSequence||Math.min(a.progress.processed,b.progress.processed))?'selected':''}>${i+1}번째 판단</option>`).join('')}</select></label><div data-lab-comparison-controls><div data-lab-frame-result role="status" aria-live="polite"></div><div data-lab-frame-retry></div></div>`:''}</div><div class="simulation-lab-grid">${panel(models[0],a,0)}${panel(models[1],b,1)}</div>`;
  else if(view==='conditions')body=`<section class="studio-sheet lab-saved-conditions"><div class="studio-sheet-head"><h3>고정한 실행 조건</h3>${button('조건을 바꿔 새 실험','clone','',running)}</div><div class="studio-sheet-body"><dl><div><dt>기간</dt><dd>${esc(date(d.startAt)+' — '+date(d.endAt))} KST</dd></div><div><dt>시세</dt><dd>${esc(market.label)}</dd></div><div><dt>초기 자금</dt><dd>${market.amount(d.initialCash)} ${esc(market.currency)}</dd></div><div><dt>수수료 · 슬리피지</dt><dd>${market.eventStream?esc(costs.feeLabel+' · 허용 가격 차이 '+costs.slippageLabel):num(d.feeBps)+'bp · '+num(d.slippageBps)+'bp'}</dd></div></dl>${graphDiff(models)}</div></section>`;
  else {const delta=referenceComparable?(completeReferenceValuation(b).metrics.totalReturn-completeReferenceValuation(a).metrics.totalReturn)*100:comparable?(b.metrics.totalReturn-a.metrics.totalReturn)*100:null,readiness=comparisonReadiness();body=`<section class="studio-sheet lab-results-summary"><div class="studio-sheet-head"><h3>비교 결과</h3>${button('판단 차이 살펴보기','view','execution',!a.progress.processed||!b?.progress.processed)}</div><div class="lab-result-delta" data-lab-comparison-summary><div class="lab-comparison-value"><span>${referenceComparable?'B − A 참고 NAV 수익률 차이':market.multiEvent?'B − A '+simulationEventReturnBasis(a).label+' 차이':market.eventStream?'B − A BTC 기준 수익률 차이':'B − A 수익률 차이'}</span><strong>${delta===null?'—':(delta>0?'+':'')+delta.toFixed(2)+'%p'}</strong></div><div class="lab-comparison-readiness"><strong>${delta===null?'전략 비교 자료 확인':'전략 비교 가능'}</strong>${readiness||(!comparable?'<span>완료된 평가 구간에서 비교합니다.</span>':'')}</div></div></section><section class="studio-sheet lab-account-results" aria-label="${referenceComparable?'참고 NAV 계좌 결과':'저장된 계좌 결과'}"><div class="studio-sheet-head"><h3>${referenceComparable?'참고 NAV 계좌 결과':'저장된 계좌 결과'}</h3></div>${delta===null?'<p class="lab-account-result-note">A/B 값은 각 계좌의 저장 원장 기준입니다. 전략 간 우열은 위의 평가 구간을 확인한 뒤 비교합니다.</p>':''}${resultRows(a,b,href,route.params.get('profileId')||'all')}</section>${[a,b].some(partialPortfolioValuation)?[a,b].map((saved,index)=>referenceValuationSources(saved,{label:index?'B':'A'})).join(''):''}<details class="lab-benchmark-detail"><summary>${market.multiEvent?'계좌 평가 기준':market.portfolio||market.eventStream?'BTC 보유와 비교':'분할매수·전액 매수와 비교'}</summary>${market.multiEvent?`<div class="studio-sheet-body">${esc(simulationEventReturnBasis(a).help)}</div>`:market.portfolio||market.eventStream?`<div class="studio-sheet-body"><span>초기 BTC를 그대로 보유한 수익률과 비교합니다.</span>${helpTooltip('BTC 기준 계산',market.eventStream?'계좌 가치를 같은 시점의 BTC 가격으로 환산해 처음부터 BTC를 보유한 경우와 비교합니다. 주문·잔고·수수료는 원래 거래쌍의 결제 통화로 기록합니다.':'모든 계좌 가치·거래 비용·수익률을 BTC로 계산합니다. 원화나 달러로 환산한 수익률은 별도 시장 가격을 사용합니다.',{id:'lab-btc-numeraire-help'})}</div>`:renderSimulationBaselineComparison([a,b].filter(Boolean))}</details>`;}
  body=(view==='conditions'?'':scopeLine(a,caps))+(finished?'':progress(a,b))+tabs+body;
 }
 return `<section class="lab-workspace" data-simulation-lab data-focus="${esc(focusedArm)}">${head}${body}${error?`<p class="lab-inline-error" role="alert">${esc(error)}</p>`:''}</section>`;
}
